<?php use App\Helpers\ViewHelper; $filters = $filters ?? ['category'=>'','author'=>'','min_price'=>null,'max_price'=>null,'sort'=>'newest']; ?><div class="container page-head"><?php require dirname(__DIR__) . '/partials/breadcrumbs.php'; ?><p class="eyebrow">Bộ sưu tập</p><h1>Tất cả sách</h1><p class="lead">Tìm sách theo danh mục, tác giả, khoảng giá và thứ tự hiển thị.</p></div><section class="container section"><form class="catalog-filters" method="get" action="/books"><div><label for="filter-category">Danh mục</label><select id="filter-category" name="category"><option value="">Tất cả danh mục</option><?php foreach ($categories ?? [] as $category): ?><option value="<?= ViewHelper::escape($category['slug']) ?>" <?= ($filters['category'] ?? '') === $category['slug'] ? 'selected' : '' ?>><?= ViewHelper::escape($category['name']) ?></option><?php endforeach; ?></select></div><div><label for="filter-author">Tác giả</label><select id="filter-author" name="author"><option value="">Tất cả tác giả</option><?php foreach ($authors ?? [] as $author): ?><option value="<?= ViewHelper::escape($author) ?>" <?= ($filters['author'] ?? '') === $author ? 'selected' : '' ?>><?= ViewHelper::escape($author) ?></option><?php endforeach; ?></select></div><div><label for="filter-min-price">Giá từ</label><input id="filter-min-price" name="min_price" type="number" min="0" step="1000" value="<?= $filters['min_price'] !== null ? (int)$filters['min_price'] : '' ?>" placeholder="VNĐ"></div><div><label for="filter-max-price">Giá đến</label><input id="filter-max-price" name="max_price" type="number" min="0" step="1000" value="<?= $filters['max_price'] !== null ? (int)$filters['max_price'] : '' ?>" placeholder="VNĐ"></div><div><label for="filter-sort">Sắp xếp</label><select id="filter-sort" name="sort"><option value="newest" <?= ($filters['sort'] ?? '') === 'newest' ? 'selected' : '' ?>>Mới nhất</option><option value="price_asc" <?= ($filters['sort'] ?? '') === 'price_asc' ? 'selected' : '' ?>>Giá thấp đến cao</option><option value="price_desc" <?= ($filters['sort'] ?? '') === 'price_desc' ? 'selected' : '' ?>>Giá cao đến thấp</option></select></div><div class="filter-actions"><button class="button button-primary" type="submit">Lọc sách</button><a class="button" href="/books">Xóa lọc</a></div></form><p class="result-note">Có <?= count($books) ?> sách phù hợp.</p><?php if ($books): ?><div class="book-grid"><?php foreach ($books as $book): ?><?php require dirname(__DIR__) . '/partials/book_card.php'; ?><?php endforeach; ?></div><?php else: ?><div class="empty-state"><h2>Không tìm thấy sách phù hợp</h2><p>Hãy thử nới rộng điều kiện lọc.</p><a class="button button-primary" href="/books">Xem toàn bộ sách</a></div><?php endif; ?></section>
